import{_ as e,o as l,c as i,a2 as s}from"./chunks/framework.DQbZ8cc1.js";const b=JSON.parse('{"title":"服务部署","description":"","frontmatter":{},"headers":[],"relativePath":"docs/installation/server/install.md","filePath":"zh/docs/installation/server/install.md"}'),t={name:"docs/installation/server/install.md"};function n(o,a,d,h,r,c){return l(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="服务部署" tabindex="-1">服务部署 <a class="header-anchor" href="#服务部署" aria-label="Permalink to “服务部署”">​</a></h1><p>本文档对应当前版本的一体化部署方式：<code>bbs-go</code> 启动后同时提供站点、后台和 API。</p><h2 id="_1-前置条件" tabindex="-1">1. 前置条件 <a class="header-anchor" href="#_1-前置条件" aria-label="Permalink to “1. 前置条件”">​</a></h2><ul><li>数据库： <ul><li>生产环境建议 MySQL 8+</li><li>本地试用可选 SQLite</li></ul></li></ul><h2 id="_2-获取与准备" tabindex="-1">2. 获取与准备 <a class="header-anchor" href="#_2-获取与准备" aria-label="Permalink to “2. 获取与准备”">​</a></h2><p>推荐使用发布包：</p><ol><li>从 Releases 下载对应平台压缩包</li><li>解压到目标目录</li><li>进入解压目录，确认存在 <code>bbs-go</code>、<code>site/</code>、<code>admin/</code>、<code>res/</code>、<code>locales/</code></li></ol><h2 id="_3-启动服务" tabindex="-1">3. 启动服务 <a class="header-anchor" href="#_3-启动服务" aria-label="Permalink to “3. 启动服务”">​</a></h2><p>在发布包目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux/macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bbs-go</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbs-go.exe</span></span></code></pre></div><p>默认端口：<code>8082</code>。</p><h2 id="_4-首次安装" tabindex="-1">4. 首次安装 <a class="header-anchor" href="#_4-首次安装" aria-label="Permalink to “4. 首次安装”">​</a></h2><p>未安装状态下，访问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;host&gt;:8082/install</span></span></code></pre></div><p>安装向导支持：</p><ul><li>语言选择：<code>en-US</code> / <code>zh-CN</code></li><li>数据库类型：MySQL / SQLite</li><li>站点信息与管理员初始化</li></ul><p>安装成功后会自动写入 <code>bbs-go.yaml</code>，并完成初始化迁移。</p><h2 id="_5-访问地址" tabindex="-1">5. 访问地址 <a class="header-anchor" href="#_5-访问地址" aria-label="Permalink to “5. 访问地址”">​</a></h2><ul><li>前台：<code>http://&lt;host&gt;:8082/</code></li><li>后台：<code>http://&lt;host&gt;:8082/admin</code></li><li>API：<code>http://&lt;host&gt;:8082/api/*</code></li></ul><h2 id="_6-生产建议" tabindex="-1">6. 生产建议 <a class="header-anchor" href="#_6-生产建议" aria-label="Permalink to “6. 生产建议”">​</a></h2><ul><li>使用 MySQL 作为生产数据库</li><li>通过反向代理（Nginx/Caddy）提供 HTTPS</li><li>定期备份数据库和上传资源</li><li>使用 systemd/supervisor/容器平台管理进程</li></ul><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to “7. 常见问题”">​</a></h2><h3 id="端口被占用" tabindex="-1">端口被占用 <a class="header-anchor" href="#端口被占用" aria-label="Permalink to “端口被占用”">​</a></h3><p>修改 <code>bbs-go.yaml</code> 中 <code>Port</code> 或释放占用端口。</p><h3 id="安装页无法进入" tabindex="-1">安装页无法进入 <a class="header-anchor" href="#安装页无法进入" aria-label="Permalink to “安装页无法进入”">​</a></h3><p>确认服务已启动，并访问 <code>/install</code>；若已安装会自动跳转首页。</p><h3 id="sqlite-说明" tabindex="-1">SQLite 说明 <a class="header-anchor" href="#sqlite-说明" aria-label="Permalink to “SQLite 说明”">​</a></h3><p>SQLite 适合本地体验和小规模试用；生产环境建议 MySQL。</p><h2 id="_8-相关文档" tabindex="-1">8. 相关文档 <a class="header-anchor" href="#_8-相关文档" aria-label="Permalink to “8. 相关文档”">​</a></h2><ul><li><a href="./google-login.html">Google 登录配置</a></li></ul>`,30)])])}const _=e(t,[["render",n]]);export{b as __pageData,_ as default};
